def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    for r in range(h):
        for c in range(w):
            if out[r][c]==3: out[r][c]=0
    # Mark the corner/edge cells of each repeated 2-pattern adjacent to the former divider.
    # For this instance, all 4x4 motifs have the same pattern; use the leading 2 cell.
    for r in range(h):
        for c in range(w):
            if out[r][c]==2 and (r==0 or out[r-1][c]==0) and (c==0 or out[r][c-1]==0):
                # top-left pixel of each motif
                if (r<4 and c%5==0) or (r>=15 and c%5==0): out[r][c]=8
    return out
